// Memory leak hazard: nonstatic inner class retains hidden reference to enclosing instance!
import java.util.ArrayList;
import java.util.List;

public class LargeDocument {
    private byte[] largeContent = new byte[10_000_000]; // 10 MB buffer

    // Flaw: nonstatic inner class implicitly holds LargeDocument.this!
    public class DocumentSnippet {
        private final String title;
        public DocumentSnippet(String title) { this.title = title; }
    }

    public DocumentSnippet createSnippet(String title) {
        return new DocumentSnippet(title);
    }
}

wrong_code.call_site:
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Object> snippets = new ArrayList<>();
        for (int i = 0; i < 1000; i++) {
            LargeDocument doc = new LargeDocument();
            // Each tiny snippet holds onto the entire 10MB LargeDocument instance!
            snippets.add(doc.createSnippet("Summary " + i));
        }
        // Crashes with java.lang.OutOfMemoryError: Java heap space!
    }
}

right_code.class:
// Safe and efficient: static member class has NO reference to enclosing instance
public class LargeDocument {
    private byte[] largeContent = new byte[10_000_000]; // 10 MB buffer

    // Static: independent instance, zero reference to enclosing LargeDocument!
    public static class DocumentSnippet {
        private final String title;
        public DocumentSnippet(String title) { this.title = title; }
        public String getTitle() { return title; }
    }

    public DocumentSnippet createSnippet(String title) {
        return new DocumentSnippet(title);
    }
}

right_code.call_site:
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<LargeDocument.DocumentSnippet> snippets = new ArrayList<>();
        for (int i = 0; i < 1000; i++) {
            LargeDocument doc = new LargeDocument();
            snippets.add(doc.createSnippet("Summary " + i));
            // doc is completely eligible for garbage collection on every iteration!
        }
        System.out.println("Created " + snippets.size() + " snippets without memory leaks!");
    }
}
